BASE='https://australianweb.agency/'
DATE='2026-10-19'
BRIEF='brief.html?service=online-stores&amp;note=Free%20Neocart%20online%20store%20-%20AUD%20999%20setup'
ARTICLES=[
 {'slug':'free-online-store-explained','title':'Free online store: what is actually free?','description':'Free plan, free trial or free software? Understand the difference and the real scope of AWA’s zero-licence online store offer.','teaser':'Look past the headline. Understand the model, the limits and the costs that belong in your budget.','label':'THE MODEL','image':'signal-zero.webp','source':'ingyenes-webaruhaz-rejtett-koltsegek','body':'models.html'},
 {'slug':'free-online-store-costs','title':'What does a free online store cost to run?','description':'Plan the real cost of a free online store: one-time setup, hosting, domain and payment fees, with a first-year and second-year budget example.','teaser':'One-time setup. Ongoing infrastructure. Fees per order. A clear framework for your first two years.','label':'THE NUMBERS','image':'signal-wave.webp','source':'mennyibe-kerul-egy-webaruhaz-2026','body':'costs.html'},
 {'slug':'start-a-free-online-store','title':'Start a free online store: seven steps to launch.','description':'Prepare your free online store for launch: products, branding, domain, payments, delivery and a complete test order. A practical AWA guide.','teaser':'From your first product list to the final test order. What to prepare before your store goes live.','label':'THE LAUNCH','image':'signal-launch.webp','source':'ingyen-webaruhaz-inditasa-lepesrol-lepesre','body':'launch.html'}
]
PAGES=['free-online-store.html','journal.html']+[a['slug']+'.html' for a in ARTICLES]

def reading_time(a):
    body=(ROOT/'_tools/journal'/a['body']).read_text(encoding='utf-8')
    return math.ceil(len(re.sub('<[^>]+>',' ',body).split())/200)

def cards(articles):
    result=[]
    for a in articles:
        href=a['slug']+'.html'
        result.append(f'''<article class="journal-card"><a class="journal-card-image" href="{href}" aria-label="{E(a['title'])}"><img src="assets/{a['image']}" srcset="assets/{a['image'].replace('.webp','-small.webp')} 800w, assets/{a['image']} 1536w" sizes="(max-width:700px) 90vw, 40vw" alt="" width="1536" height="1024" loading="lazy" decoding="async"><span>{a['label']} / {reading_time(a)} MIN</span></a><div class="journal-card-text"><span class="mono">19 OCT 2026 · COMMERCE</span><h3><a href="{href}">{E(a['title'])}</a></h3><p>{E(a['teaser'])}</p><a class="text-link" href="{href}" aria-label="Read article: {E(a['title'])}">Read the story <span aria-hidden="true">↗</span></a></div></article>''')
    return ''.join(result)

def recommendations(page):
    selected=[a for a in ARTICLES if a['slug']+'.html'!=page]
    return f'''<section class="journal-recommendations" aria-labelledby="journal-recommendations-title"><div class="wrap"><div class="journal-heading"><div><p class="label">AWA Journal / Free online stores</p><h2 id="journal-recommendations-title">A little clarity.<br><em>A better start.</em></h2></div><a class="text-link" href="journal.html">Explore the journal <span aria-hidden="true">↗</span></a></div><div class="journal-cards" data-count="{len(selected)}">{cards(selected)}</div></div></section>'''

def shell(path,title,description,main,bodyclass='',schema=None,image='signal-zero.webp'):
    url=BASE+path
    ld=json.dumps(schema,ensure_ascii=False,separators=(',',':')) if schema else ''
    return f'''<!doctype html><html lang="en-AU"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>{E(title)} | AWA</title><meta name="description" content="{E(description)}"><link rel="canonical" href="{url}">
<meta name="theme-color" content="#191a18"><link rel="icon" href="favicon.ico"><link rel="apple-touch-icon" href="apple-touch-icon.png">
<link rel="preload" as="font" href="fonts/dm-sans-latin.woff2" type="font/woff2" crossorigin>
<link rel="stylesheet" href="awa.css"><link rel="stylesheet" href="signal.css">
<meta property="og:type" content="{'article' if bodyclass=='journal-article' else 'website'}"><meta property="og:locale" content="en_AU"><meta property="og:site_name" content="AWA — Australian Web Agency">
<meta property="og:title" content="{E(title)}"><meta property="og:description" content="{E(description)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{BASE}assets/{image}"><meta name="twitter:card" content="summary_large_image">
<script src="awa.js" defer></script><script src="commerce.js" defer></script>
{'<script type="application/ld+json">'+ld+'</script>' if ld else ''}
</head><body class="{bodyclass}">
<!-- header --><!-- /header -->
<main id="main" tabindex="-1">{main}
<!-- contact --><!-- /contact -->
</main><!-- footer --><!-- /footer -->
</body></html>'''

def promo():
    return f'''<section class="store-promo" id="free-store" aria-labelledby="free-store-title"><div class="wrap store-promo-grid"><div><p class="label">A new way to start / Neocart × AWA</p><h2 id="free-store-title">Your next chapter.<br><em>Zero licence fees.</em></h2><p>A ready-to-launch online store, configured with you. Put your budget into your products and your business, with no monthly fee for the base shop software.</p><p class="promo-cost"><strong>A$0 software · A$999 one-time setup</strong></p><p class="promo-fine">Setup is A$999 plus GST. Hosting and domain are separate. External provider fees apply.</p><a class="btn btn-lime" href="free-online-store.html">Meet your free online store <span aria-hidden="true">↗</span></a></div><figure class="store-promo-visual"><img src="assets/signal-zero.webp" srcset="assets/signal-zero-small.webp 800w, assets/signal-zero.webp 1536w" sizes="(max-width:700px) 90vw, 50vw" alt="Sculptural silver zero and unbranded products in an orange-lit gallery" width="1536" height="1024" loading="lazy"><span class="free-seal" aria-label="Zero Australian dollar software licence">A$0</span><figcaption class="visual-label">YOUR STORE. YOUR BRAND. YOUR NEXT MOVE.</figcaption></figure></div></section>'''

